insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-pe-126","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lanthanoids and actinoids are written as two separate rows beneath the main table so that","options":["they are excluded from the periodic law","the 18-column long form remains compact","they can be treated as noble gases","their atomic numbers can be ignored"],"answer_index":1,"explanation":"Inserting fourteen extra cells into periods 6 and 7 would make those rows awkwardly wide.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-127","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fourteen lanthanoids still belong chemically to which period of the long form table?","options":["period 4","period 5","period 6","period 7"],"answer_index":2,"explanation":"They follow lanthanum in period 6; actinoids similarly belong to period 7.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-128","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Moseley found that the square root of the characteristic X-ray frequency varies linearly with atomic number as $\\sqrt{\\nu}=a(Z-b)$. This showed that","options":["atomic mass is still the fundamental index","Z, not A, is the property that orders the elements","neutrons determine chemical behaviour","X-rays arise from valence-shell jumps only"],"answer_index":1,"explanation":"A plot of $\\sqrt{\\nu}$ against Z is a straight line; plots against atomic mass are irregular, so Z is the true periodic argument.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-129","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Alkali metals and alkaline earth metals together constitute the","options":["p-block","s-block","d-block","f-block"],"answer_index":1,"explanation":"Their differentiating electron enters the ns subshell (groups 1 and 2).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-130","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The p-block of the long form table begins at boron and ends at","options":["the alkaline earth metals","the noble gases of each period","the lanthanoids","hydrogen only"],"answer_index":1,"explanation":"Groups 13–18 are p-block; the last member of each of these periods is a noble gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-131","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"d-block elements are those whose differentiating electron enters a","options":["ns subshell","np subshell","penultimate (n−1)d subshell","(n−2)f subshell"],"answer_index":2,"explanation":"That is the definition of the transition series occupying groups 3–12.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-132","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lanthanoids and actinoids together constitute the","options":["s-block","p-block","d-block","f-block"],"answer_index":3,"explanation":"Their differentiating electron enters the (n−2)f subshell; they are the inner transition elements.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-133","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Hydrogen and helium are the only two members of the","options":["second period","first period","d-block","halogen family"],"answer_index":1,"explanation":"Period 1 fills the 1s subshell and therefore contains just H and He.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-134","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A short period of eight members starts at lithium and ends at","options":["argon","neon","sodium","fluorine"],"answer_index":1,"explanation":"Period 2 fills 2s and 2p (2 + 6 = 8 elements) from Li to Ne.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-135","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sodium through argon form the second short period, matching the length of the","options":["lithium–neon row","potassium–krypton row","scandium–zinc row","cerium–lutetium row"],"answer_index":0,"explanation":"Period 3 also has eight elements (3s and 3p); 3d is not yet available.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
